// ─────────────────────────────────────────────────────────────
//  AKARI WAITLIST · CONFIG — the only node you should need to edit
// ─────────────────────────────────────────────────────────────
const cfg = {
  // Connections
  airtableBaseId: 'appXXXXXXXXXXXXXX', // from the base URL: airtable.com/appXXXX/...
  publicWebhookBase: 'https://YOUR-N8N-HOST/webhook/akari-waitlist', // production webhook URL prefix, no trailing slash
  airtableApi: 'https://api.airtable.com/v0',
  sendgridApi: 'https://api.sendgrid.com/v3/mail/send',
  tables: { waitlist: 'Waitlist', capacity: 'Capacity', log: 'Activity Log' },

  // Email identity (fromEmail must be a verified SendGrid sender / domain)
  brandName: 'Akari Sauna',
  fromEmail: 'waitlist@YOUR-DOMAIN.com',
  fromName: 'Akari Sauna',
  replyToEmail: 'hello@YOUR-DOMAIN.com',
  teamEmails: ['team@YOUR-DOMAIN.com'], // daily report + tour-request alerts

  // Email content (confirmed with Jack, 9 Oct)
  membershipPageUrl: 'https://www.akarisauna.com/membership', // same for every location
  priceByTier: { Unlimited: 220, Daytime: 165, '4-Visit': 140 }, // $/month; no "Summer Pass" price yet — update when it's live on the form

  // Tours: "Tour first" sends people to their location's Cal.com page. Blank = the old "when suits you?" box.
  tourBookingUrlByLocation: {
    Williamsburg: 'https://akari-sauna.cal.com/akari-williamsburg/akari-williamsburg-tours',
    Greenpoint: 'https://akari-sauna.cal.com/akari-greenpoint/akari-greenpoint-tours',
    'Lower East Side': 'https://akari-sauna.cal.com/hello/akari-les-tours',
  }, // from Jack, 28 Oct
  tourReleaseHours: 48, // a tour hold is released this long after the booked tour, unless a sign-up link was sent
  calWebhookSecret: 'CHANGE-ME', // long random string; goes on the end of the Cal.com webhook URL (?k=...)

  // Safety switches — leave as-is until testing is signed off
  engineEnabled: true, // false = the hourly engine does nothing (webhooks still work)
  sandboxMode: true, // true = SendGrid accepts but delivers nothing
  testRecipient: '', // e.g. 'you@yourdomain.com' → every email is redirected here, except to allowedRecipients (you get a [COPY] of theirs)
  allowedRecipients: [], // only used while testRecipient is set. People here get their email for real: 'name@x.com' (also matches name+2@x.com) or '@yourdomain.com' for a whole domain
  sendNowSecret: 'CHANGE-ME', // long random string; also goes in the Airtable button URL

  // Business rules
  timezone: 'America/New_York',
  sendWindow: { startHour: 8, endHour: 20 }, // invites + heads-ups only go out 08:00–19:59 local
  holdHours: 48, // claim window that holds the spot (Jack, 27 Oct: 48h)
  primeCount: 10, // "next ~10 in line" get the early heads-up
  newMemberWeight: 3, // 1 new signup ≈ 3 existing-member upgrades
  warmCooldownHours: 72, // a timed-out person is first in line again after this
  timeoutsBeforeNoReply: 2, // 1st timeout → Warm, 2nd → No Reply bucket
  maxInvitesPerQueuePerRun: 10, // guardrail against a mistyped minimum
};

const base = `${cfg.airtableApi}/${cfg.airtableBaseId}`;
cfg.urls = {
  waitlist: `${base}/${encodeURIComponent(cfg.tables.waitlist)}`,
  capacity: `${base}/${encodeURIComponent(cfg.tables.capacity)}`,
  log: `${base}/${encodeURIComponent(cfg.tables.log)}`,
};

return $input.all().map((item) => ({ json: { ...item.json, cfg } }));

// Reads the raw Typeform webhook payload. Fields are detected by answer type and
// by matching choice labels, so question wording/refs can change without edits here.
const LOCATIONS = [
  ['lowereastside', 'Lower East Side'],
  ['williamsburg', 'Williamsburg'],
  ['greenpoint', 'Greenpoint'],
];
// A choice label can mean more than one location (e.g. "All-Access (both locations)").
// Checked before the single-location dictionary below.
const LOCATION_ALIASES = [
  ['allaccess', ['Williamsburg', 'Greenpoint']],
];
const MEMBERSHIPS = [
  ['unlimited', 'Unlimited'],
  ['daytime', 'Daytime'],
  ['4visit', '4-Visit'],
  ['fourvisit', '4-Visit'],
  ['summerpass', 'Summer Pass'],
];
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const matchLocations = (label) => {
  const n = norm(label);
  if (!n) return [];
  if (n === 'les') return ['Lower East Side'];
  const alias = LOCATION_ALIASES.find(([key]) => n.includes(key));
  if (alias) return alias[1];
  const hit = LOCATIONS.find(([key]) => n.includes(key));
  return hit ? [hit[1]] : [];
};
const matchLabel = (label, dict) => {
  const n = norm(label);
  if (!n) return null;
  const hit = dict.find(([key]) => n.includes(key));
  return hit ? hit[1] : null;
};
const EXISTING_Q = /(existing|current|already).*member|member.*(already|currently)/i;
const ZIP_Q = /zip|postal/i;
const REFERRAL_Q = /how.*(hear|find).*(us|about)/i;

const fr = (($('Config').first().json.body) || {}).form_response;
if (!fr) throw new Error('Intake: payload is not a Typeform form_response');

const titles = Object.fromEntries((fr.definition?.fields || []).map((f) => [f.id, f.title || '']));
let email = '';
let phone = '';
let firstText = '';
let zipCode = '';
let referralSource = '';
let existing = false;
const nameParts = [];
const locations = new Set();
const memberships = new Set();

for (const a of fr.answers || []) {
  // Typeform's "Contact Info" block delivers one answer per sub-field (first/last name, phone,
  // email), each with its own field.id — these usually aren't in definition.fields, so title
  // lookup falls back to field.ref. If a real submission shows ref isn't descriptive either,
  // the /name/i check below may need to key off answer order instead — confirm against one
  // real payload before relying on this for anything beyond name/email/phone.
  const title = titles[a.field?.id] || a.field?.ref || '';
  let labels = [];
  if (a.type === 'email') email = email || a.email;
  else if (a.type === 'phone_number') phone = phone || a.phone_number;
  else if (a.type === 'text') {
    if (/name/i.test(title)) nameParts.push(a.text);
    else if (ZIP_Q.test(title)) zipCode = a.text;
    else if (REFERRAL_Q.test(title)) referralSource = a.text;
    else if (!firstText) firstText = a.text;
  } else if (a.type === 'boolean') {
    if (EXISTING_Q.test(title)) existing = !!a.boolean;
  } else if (a.type === 'choice') labels = [a.choice?.label, a.choice?.other];
  else if (a.type === 'choices') labels = [...(a.choices?.labels || []), a.choices?.other];

  if (labels.length && EXISTING_Q.test(title)) existing = labels.some((l) => /^yes/i.test(String(l || '')));
  if (labels.length && REFERRAL_Q.test(title)) referralSource = referralSource || labels.filter(Boolean).join(', ');
  for (const l of labels) {
    matchLocations(l).forEach((loc) => locations.add(loc));
    const mem = matchLabel(l, MEMBERSHIPS);
    if (mem) memberships.add(mem);
  }
}

if (!email || !locations.size || !memberships.size) {
  throw new Error(
    `Intake: submission ${fr.token} is missing ${[!email && 'email', !locations.size && 'location', !memberships.size && 'membership'].filter(Boolean).join(', ')} — check the Typeform choice labels`,
  );
}

return [{
  json: {
    email: email.trim().toLowerCase(),
    name: nameParts.join(' ').trim() || firstText || '',
    phone,
    zipCode,
    referralSource,
    memberType: existing ? 'Existing' : 'New',
    joinedAt: fr.submitted_at || new Date().toISOString(),
    submissionId: fr.token,
    queues: [...locations].flatMap((location) => [...memberships].map((membership) => ({ location, membership }))),
  },
}];

// ── shared helpers: core ─────────────────────────────
const CFG = $('Config').first().json.cfg;
const NOW = new Date();
const ACTIVE_STATUSES = ['Waiting', 'Primed', 'Invited', 'Tour Requested', 'Warm', 'Not Right Now', 'No Reply'];
const HOLD_STATUSES = ['Invited', 'Tour Requested'];
const HOUR = 3600000;
const DAY = 86400000;

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const toDate = (v) => (v ? new Date(v) : null);
const firstName = (n) => String(n || '').trim().split(/\s+/)[0] || 'there';
const article = (word) => (/^[aeiou]/i.test(String(word || '')) ? 'an' : 'a');
const recordsOf = (nodeName) => $(nodeName).all().flatMap((i) => i.json.records || []);
const fmtTime = (d) =>
  new Date(d).toLocaleString('en-US', {
    timeZone: CFG.timezone, weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short',
  });

// Real tokens come from the "Generate Tokens" (Crypto) node in the executor; Code nodes can't
// reliably reach secure randomness, so they emit this placeholder instead.
const TOKEN = '__TOKEN__';

function normEntry(r) {
  const f = r.fields || {};
  return {
    id: r.id,
    name: f['Name'] || '',
    email: String(f['Email'] || '').trim().toLowerCase(),
    phone: f['Phone'] || '',
    location: f['Location'] || '',
    membership: f['Membership'] || '',
    memberType: f['Member Type'] === 'Existing' ? 'Existing' : 'New',
    joinedAt: toDate(f['Joined At']) || toDate(r.createdTime) || NOW,
    manualRank: typeof f['Manual Rank'] === 'number' ? f['Manual Rank'] : null,
    status: f['Status'] || 'Waiting',
    token: f['Invite Token'] || '',
    invitedAt: toDate(f['Invited At']),
    expiresAt: toDate(f['Invite Expires At']),
    source: f['Invite Source'] || '',
    timeoutCount: Number(f['Timeout Count'] || 0),
    primedAt: toDate(f['Primed At']),
    responseAt: toDate(f['Response At']),
    tourNotes: f['Tour Notes'] || '',
    tourAt: toDate(f['Tour At']),
  };
}

// Cal.com booking page for this person's location (blank if none is set), pre-filled with their name
// and email, and tagged with their row ID so the booking notification can be matched back to them.
function tourBookingUrl(e) {
  const base = String((CFG.tourBookingUrlByLocation || {})[e.location] || '').trim();
  if (!base) return '';
  const params = [['name', e.name], ['email', e.email], ['metadata[entry]', e.id]]
    .filter(([, v]) => v)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join('&');
  return `${base}${base.includes('?') ? '&' : '?'}${params}`;
}

function logRow(e, event, extra = {}) {
  return {
    Summary: `${event} · ${e.email}`,
    Timestamp: NOW.toISOString(),
    Event: event,
    Email: e.email,
    Name: e.name,
    Location: e.location,
    Membership: e.membership,
    'Entry ID': e.id,
    ...extra,
  };
}
// ── end core ─────────────────────────────────────────
const p = $('Parse Typeform').first().json;
// A signup in the last 60 days (the window the engine still counts) means they hold that membership now.
const recentSignup = (e) => e.status === 'Signed Up' && (!e.responseAt || NOW - e.responseAt < 60 * DAY);
const already = new Set(
  recordsOf('Find Existing Entries')
    .map(normEntry)
    .filter((e) => ACTIVE_STATUSES.includes(e.status) || recentSignup(e))
    .map((e) => `${e.location}|${e.membership}`),
);

const rows = p.queues
  .filter((q) => !already.has(`${q.location}|${q.membership}`))
  .map((q) => ({
    fields: {
      Name: p.name,
      Email: p.email,
      Phone: p.phone,
      'Zip Code': p.zipCode,
      'Referral Source': p.referralSource,
      Location: q.location,
      Membership: q.membership,
      'Member Type': p.memberType,
      'Entry Source': 'Typeform',
      'Joined At': p.joinedAt,
      Status: 'Waiting',
      'Timeout Count': 0,
    },
  }));

// Airtable accepts at most 10 records per create request. An empty batch means "nothing new".
if (!rows.length) return [{ json: { records: [], typecast: true } }];
const out = [];
for (let i = 0; i < rows.length; i += 10) out.push({ json: { records: rows.slice(i, i + 10), typecast: true } });
return out;

// ── shared helpers: core ─────────────────────────────
const CFG = $('Config').first().json.cfg;
const NOW = new Date();
const ACTIVE_STATUSES = ['Waiting', 'Primed', 'Invited', 'Tour Requested', 'Warm', 'Not Right Now', 'No Reply'];
const HOLD_STATUSES = ['Invited', 'Tour Requested'];
const HOUR = 3600000;
const DAY = 86400000;

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const toDate = (v) => (v ? new Date(v) : null);
const firstName = (n) => String(n || '').trim().split(/\s+/)[0] || 'there';
const article = (word) => (/^[aeiou]/i.test(String(word || '')) ? 'an' : 'a');
const recordsOf = (nodeName) => $(nodeName).all().flatMap((i) => i.json.records || []);
const fmtTime = (d) =>
  new Date(d).toLocaleString('en-US', {
    timeZone: CFG.timezone, weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short',
  });

// Real tokens come from the "Generate Tokens" (Crypto) node in the executor; Code nodes can't
// reliably reach secure randomness, so they emit this placeholder instead.
const TOKEN = '__TOKEN__';

function normEntry(r) {
  const f = r.fields || {};
  return {
    id: r.id,
    name: f['Name'] || '',
    email: String(f['Email'] || '').trim().toLowerCase(),
    phone: f['Phone'] || '',
    location: f['Location'] || '',
    membership: f['Membership'] || '',
    memberType: f['Member Type'] === 'Existing' ? 'Existing' : 'New',
    joinedAt: toDate(f['Joined At']) || toDate(r.createdTime) || NOW,
    manualRank: typeof f['Manual Rank'] === 'number' ? f['Manual Rank'] : null,
    status: f['Status'] || 'Waiting',
    token: f['Invite Token'] || '',
    invitedAt: toDate(f['Invited At']),
    expiresAt: toDate(f['Invite Expires At']),
    source: f['Invite Source'] || '',
    timeoutCount: Number(f['Timeout Count'] || 0),
    primedAt: toDate(f['Primed At']),
    responseAt: toDate(f['Response At']),
    tourNotes: f['Tour Notes'] || '',
    tourAt: toDate(f['Tour At']),
  };
}

// Cal.com booking page for this person's location (blank if none is set), pre-filled with their name
// and email, and tagged with their row ID so the booking notification can be matched back to them.
function tourBookingUrl(e) {
  const base = String((CFG.tourBookingUrlByLocation || {})[e.location] || '').trim();
  if (!base) return '';
  const params = [['name', e.name], ['email', e.email], ['metadata[entry]', e.id]]
    .filter(([, v]) => v)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join('&');
  return `${base}${base.includes('?') ? '&' : '?'}${params}`;
}

function logRow(e, event, extra = {}) {
  return {
    Summary: `${event} · ${e.email}`,
    Timestamp: NOW.toISOString(),
    Event: event,
    Email: e.email,
    Name: e.name,
    Location: e.location,
    Membership: e.membership,
    'Entry ID': e.id,
    ...extra,
  };
}
// ── end core ─────────────────────────────────────────
// ── shared helpers: email ─────────────────────────────
function emailLayout(bodyHtml, preheader) {
  // Hidden preheader: shows as the preview snippet in the inbox list without appearing in the body.
  // The repeated &zwnj;&nbsp; padding stops the client pulling real body text in after a short preheader.
  const pre = preheader
    ? `<div style="display:none;font-size:1px;color:#f4f1ec;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all">${esc(preheader)}${'&zwnj;&nbsp;'.repeat(40)}</div>`
    : '';
  return `<!doctype html><html><body style="margin:0;padding:0;background:#f4f1ec;font-family:Helvetica,Arial,sans-serif;color:#1f1d1a">
${pre}<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:8px">
<tr><td style="padding:28px 28px 4px 28px;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#8a7f72">${esc(CFG.brandName)}</td></tr>
<tr><td style="padding:8px 28px 28px 28px;font-size:16px;line-height:1.55">${bodyHtml}</td></tr>
</table></td></tr></table></body></html>`;
}

function btn(href, label, primary = false) {
  const style = primary
    ? 'background:#1f1d1a;color:#ffffff;border:1px solid #1f1d1a'
    : 'background:#ffffff;color:#1f1d1a;border:1px solid #c9c1b6';
  return `<a href="${esc(href)}" style="display:block;${style};text-decoration:none;text-align:center;padding:12px 16px;border-radius:6px;margin:8px 0;font-size:15px">${esc(label)}</a>`;
}

function respondLink(token, action) {
  return `${CFG.publicWebhookBase}/respond?t=${encodeURIComponent(token)}&a=${action}`;
}

function inviteEmail(e, token, expires) {
  const until = fmtTime(expires);
  const price = CFG.priceByTier && CFG.priceByTier[e.membership];
  const costLine = price
    ? `The cost for your membership will be $${price}/month, and additional membership details can be found on our membership page here ${CFG.membershipPageUrl}.`
    : `Additional membership details, including pricing, can be found on our membership page here ${CFG.membershipPageUrl}.`;
  const pageLink = `<a href="${esc(CFG.membershipPageUrl)}" style="color:#1f1d1a">${esc(CFG.membershipPageUrl)}</a>`;
  const costHtml = esc(costLine).replace(esc(CFG.membershipPageUrl), pageLink);
  const html = emailLayout(`
<p>Hi ${esc(firstName(e.name))},</p>
<p>We really appreciate your patience during the waitlist process for the ${esc(e.membership)} membership at Akari ${esc(e.location)}. We are in the process of opening more memberships this month, and we would love to have you join us!</p>
<p>${costHtml} We'll hold it for you until <strong>${esc(until)}</strong>. After that it goes to the next person in line.</p>
<p>Please let us know how you would like to proceed below:</p>
${btn(respondLink(token, 'yes'), 'Sign up', true)}
${btn(respondLink(token, 'tour'), 'Tour first')}
<p style="font-size:13px;color:#8a7f72;margin:-4px 0 12px">We'll find a time for you to come see the space before you commit.</p>
${btn(respondLink(token, 'notnow'), 'Not ready yet')}
<p style="font-size:13px;color:#8a7f72;margin:-4px 0 12px">We'll keep you on the waitlist and check back in with you down the road.</p>
${btn(respondLink(token, 'no'), 'No longer interested')}
<p>If you are waiting for another membership type, and would like to sign up for this one in the meantime, please feel free to do so, and we will keep you on the waitlist for your preferred membership.</p>
<p>For any questions about the membership or Akari in general, please reply to this email and we will get back to you shortly.</p>
<p>We look forward to welcoming you soon!</p>
<p>Warmly,<br>Akari team</p>`, 'Your spot is available for a limited time');
  const text = `Hi ${firstName(e.name)},

We really appreciate your patience during the waitlist process for the ${e.membership} membership at Akari ${e.location}. We are in the process of opening more memberships this month, and we would love to have you join us!

${costLine} We'll hold it for you until ${until}. After that it goes to the next person in line.

Please let us know how you would like to proceed below:
Sign up: ${respondLink(token, 'yes')}
Tour first: ${respondLink(token, 'tour')} (we'll find a time for you to come see the space before you commit)
Not ready yet: ${respondLink(token, 'notnow')} (we'll keep you on the waitlist and check back in with you down the road)
No longer interested: ${respondLink(token, 'no')}

If you are waiting for another membership type, and would like to sign up for this one in the meantime, please feel free to do so, and we will keep you on the waitlist for your preferred membership.

For any questions about the membership or Akari in general, please reply to this email and we will get back to you shortly.

We look forward to welcoming you soon!

Warmly,
Akari team`;
  return { to: e.email, name: e.name, subject: `${e.membership} Membership Now Available at Akari ${e.location}`, html, text };
}

// Jack's confirmation copy (template 2): the private Glofox sign-up link. Unlimited signups are told
// they'll come off other waitlists; lower tiers stay on them, with a one-click way off.
function confirmationEmail(e, signupUrl, { removedOthers = false, stillOn = false } = {}) {
  const linkText = signupUrl || '(signup link pending — we\'ll send it shortly)';
  const linkHtml = signupUrl ? `<a href="${esc(signupUrl)}" style="color:#1f1d1a">${esc(signupUrl)}</a>` : esc(linkText);
  const leave = respondLink(e.token, 'leave');
  const overlap = removedOthers
    ? `<p>Once you sign up for your Unlimited membership, we'll automatically remove you from any other Akari waitlists you've joined.</p>`
    : stillOn
      ? `<p>You'll stay on any other Akari waitlists you've joined. If you'd rather come off them, you can remove yourself here: <a href="${esc(leave)}" style="color:#1f1d1a">${esc(leave)}</a></p>`
      : '';
  const html = emailLayout(`
<p>Hi ${esc(firstName(e.name))},</p>
<p>Thank you for your interest in joining Akari! Here is your private sign up link for your ${esc(e.membership)} membership at Akari ${esc(e.location)}: ${linkHtml}</p>
${overlap}
<p>Please let us know if you have any issues signing up!</p>
<p>Warmly,<br>Akari team</p>`, `Your ${e.membership} membership is ready for you`);
  const text = `Hi ${firstName(e.name)},

Thank you for your interest in joining Akari! Here is your private sign up link for your ${e.membership} membership at Akari ${e.location}: ${linkText}

${removedOthers
    ? 'Once you sign up for your Unlimited membership, we\'ll automatically remove you from any other Akari waitlists you\'ve joined.'
    : stillOn ? `You'll stay on any other Akari waitlists you've joined. If you'd rather come off them, you can remove yourself here: ${leave}` : ''}

Please let us know if you have any issues signing up!

Warmly,
Akari team`;
  return { to: e.email, name: e.name, subject: `Your Private Sign Up Link for Akari ${e.location}`, html, text };
}

// Test mode (testRecipient set) redirects every email to that one inbox, except to people on
// allowedRecipients, who get theirs for real. An entry is an address ('jack@x.com', which also
// matches jack+2@x.com) or a whole domain ('@akarisauna.com').
const mailKey = (a) => {
  const [local, domain] = String(a || '').trim().toLowerCase().split('@');
  return `${(local || '').split('+')[0]}@${domain || ''}`;
};
function isAllowedRecipient(address) {
  const key = mailKey(address);
  return (CFG.allowedRecipients || []).some((entry) => {
    const e = String(entry || '').trim().toLowerCase();
    return e.startsWith('@') ? key.endsWith(e) : key === mailKey(e);
  });
}

function sendgridPayload(m) {
  const list = (Array.isArray(m.to) ? m.to : [m.to]).filter(Boolean);
  let to = list.map((email) => (m.name && list.length === 1 ? { email, name: m.name } : { email }));
  let subject = m.subject;
  const personalizations = [{ to }];
  if (CFG.testRecipient) {
    const sentForReal = list.length && list.every(isAllowedRecipient);
    if (!sentForReal) {
      subject = `[TEST → ${list.join(', ')}] ${subject}`;
      personalizations[0].to = [{ email: CFG.testRecipient }];
    } else if (!list.some((a) => a.trim().toLowerCase() === CFG.testRecipient.trim().toLowerCase())) {
      // Delivered for real, and the test inbox gets its own labelled copy (SendGrid sends each personalization separately).
      personalizations.push({ to: [{ email: CFG.testRecipient }], subject: `[COPY → ${list.join(', ')}] ${subject}` });
    }
  }
  return {
    personalizations,
    from: { email: CFG.fromEmail, name: CFG.fromName },
    reply_to: { email: CFG.replyToEmail || CFG.fromEmail },
    subject,
    content: [
      { type: 'text/plain', value: m.text },
      { type: 'text/html', value: m.html },
    ],
    // Click tracking would rewrite the response links; keep them direct.
    tracking_settings: { click_tracking: { enable: false, enable_text: false }, open_tracking: { enable: false } },
    mail_settings: { sandbox_mode: { enable: !!CFG.sandboxMode } },
  };
}
// ── end email ─────────────────────────────────────────
// Decides everything for this run; the executor nodes downstream carry it out.
// Each output item = { recordId, fields, email|null, log }.
if (!CFG.engineEnabled) return [];

const localHour = Number(new Intl.DateTimeFormat('en-US', { hour: 'numeric', hourCycle: 'h23', timeZone: CFG.timezone }).format(NOW));
const inSendWindow = localHour >= CFG.sendWindow.startHour && localHour < CFG.sendWindow.endHour;

const entries = recordsOf('Get Active Entries').map(normEntry);
const queues = recordsOf('Get Capacity')
  .map((r) => ({
    location: r.fields['Location'],
    membership: r.fields['Membership'],
    min: Number(r.fields['Minimum Members'] || 0),
    active: Number(r.fields['Active Members'] || 0),
    countedAt: toDate(r.fields['Active Updated At']) || new Date(0),
    newOnly: !!r.fields['Prioritise New Only'],
    enabled: !!r.fields['Enabled'],
    hasSignupUrl: !!r.fields['Signup URL'],
  }))
  .filter((q) => q.enabled && q.location && q.membership);

const actions = [];

// 1. Expire holds whose window (holdHours) passed with no reply (runs around the clock).
for (const e of entries) {
  if (e.status === 'Invited' && e.expiresAt && e.expiresAt <= NOW) {
    const timeouts = e.timeoutCount + 1;
    const next = timeouts >= CFG.timeoutsBeforeNoReply ? 'No Reply' : 'Warm';
    actions.push({
      recordId: e.id,
      fields: { Status: next, 'Timeout Count': timeouts },
      email: null,
      log: logRow(e, 'Timed Out', { Source: e.source || 'Auto', Detail: `No reply within ${CFG.holdHours}h → ${next}` }),
    });
    e.status = next;
    e.timeoutCount = timeouts;
  }
}

// 1b. Release a tour hold once the tour is tourReleaseHours past and no sign-up link was sent (that
// would have made them Signed Up). Staff own the follow-up from here, so no automatic re-invite.
for (const e of entries) {
  if (e.status === 'Tour Requested' && e.tourAt && NOW - e.tourAt >= CFG.tourReleaseHours * HOUR) {
    actions.push({
      recordId: e.id,
      fields: { Status: 'Not Right Now', Reason: `Toured ${fmtTime(e.tourAt)}; no sign-up link sent within ${CFG.tourReleaseHours}h` },
      email: null,
      log: logRow(e, 'Tour Released', { Detail: `Tour on ${fmtTime(e.tourAt)}; no sign-up link sent within ${CFG.tourReleaseHours}h, so the spot was released → Not Right Now` }),
    });
    e.status = 'Not Right Now';
  }
}

if (!inSendWindow) return actions.map((a) => ({ json: a }));

// 2. Priority order: manual rank → warm → weighted wait (new members count x newMemberWeight) → joined first.
const weightedWait = (e) => (Math.max(0, NOW - e.joinedAt) / DAY) * (e.memberType === 'Existing' ? 1 : CFG.newMemberWeight);
// The cool-down only applies to people who ignored their invite. Any reply since it was sent
// ('Response At' is cleared on every new invite) means they asked to be first in line.
function inCooldown(e) {
  if (e.status !== 'Warm' || !e.expiresAt || e.responseAt) return false;
  return NOW - e.expiresAt < CFG.warmCooldownHours * HOUR;
}
function lineFor(q, inQueue) {
  return inQueue
    .filter((e) => ['Waiting', 'Primed', 'Warm'].includes(e.status))
    .filter((e) => !q.newOnly || e.memberType !== 'Existing')
    .sort((a, b) => {
      if (a.manualRank !== b.manualRank) {
        if (a.manualRank === null) return 1;
        if (b.manualRank === null) return -1;
        return a.manualRank - b.manualRank;
      }
      const warmA = a.status === 'Warm' ? 0 : 1;
      const warmB = b.status === 'Warm' ? 0 : 1;
      if (warmA !== warmB) return warmA - warmB;
      const byWait = weightedWait(b) - weightedWait(a);
      if (byWait !== 0) return byWait;
      return a.joinedAt - b.joinedAt;
    });
}

// One live invite / tour hold per person across all queues.
const engaged = new Set(entries.filter((e) => HOLD_STATUSES.includes(e.status)).map((e) => e.email));
const primeGroups = new Map();

for (const q of queues) {
  const inQueue = entries.filter((e) => e.location === q.location && e.membership === q.membership);
  const pendingSignups = inQueue.filter((e) => e.status === 'Signed Up' && e.responseAt && e.responseAt > q.countedAt).length;
  const holds = inQueue.filter((e) => HOLD_STATUSES.includes(e.status)).length;
  const gap = q.min - q.active - pendingSignups - holds;
  const line = lineFor(q, inQueue);

  // 3. Invite enough people to fill the gap (no signup URL = misconfigured queue, flagged in the daily report).
  let slots = q.hasSignupUrl ? Math.max(0, Math.min(gap, CFG.maxInvitesPerQueuePerRun)) : 0;
  const invitedNow = new Set();
  for (const e of line) {
    if (slots <= 0) break;
    if (inCooldown(e) || engaged.has(e.email)) continue;
    const expires = new Date(NOW.getTime() + CFG.holdHours * HOUR);
    actions.push({
      recordId: e.id,
      fields: {
        Status: 'Invited', 'Invite Token': TOKEN, 'Invited At': NOW.toISOString(),
        'Invite Expires At': expires.toISOString(), 'Invite Source': 'Auto', 'Response At': null,
      },
      email: inviteEmail(e, TOKEN, expires),
      log: logRow(e, 'Invited', { Source: 'Auto', Detail: `${e.status === 'Warm' ? 'Warm re-invite. ' : ''}Held until ${fmtTime(expires)}` }),
    });
    engaged.add(e.email);
    invitedNow.add(e.id);
    slots--;
  }

  // 4. Early heads-up for the next N in line who haven't had one.
  for (const e of line.filter((x) => !invitedNow.has(x.id)).slice(0, CFG.primeCount)) {
    if (e.status !== 'Waiting' || e.primedAt || engaged.has(e.email)) continue;
    if (!primeGroups.has(e.email)) primeGroups.set(e.email, []);
    primeGroups.get(e.email).push(e);
  }
}

// Jack's "heads up" copy (template 3). Opting out is by reply until a one-click remove link is agreed.
function primeEmail(list) {
  const e = list[0];
  const what = list.map((x) => `the ${x.membership} membership at Akari ${x.location}`).join(' and ');
  const locations = [...new Set(list.map((x) => x.location))];
  const subject = list.length === 1
    ? `You're Almost Up for ${article(e.membership)} ${e.membership} Membership at Akari ${e.location}`
    : locations.length === 1 ? `You're Almost Up for a Membership at Akari ${locations[0]}` : "You're Almost Up for an Akari Membership";
  const paras = [
    `Thank you for your continued patience on the waitlist for ${what}. We wanted to give you a heads up that you're now close to the front of the line, and a spot could open up any day now.`,
    `When it does, we'll send you an email with all the details, and you'll have ${CFG.holdHours} hours to claim your spot.`,
    "If you're still interested, there's nothing you need to do. If your plans have changed, just reply to this email and we'll remove you from the waitlist.",
    'For any questions about the membership or Akari in general, please reply to this email and we will get back to you shortly.',
    'We look forward to welcoming you soon!',
  ];
  const html = emailLayout(`
<p>Hi ${esc(firstName(e.name))},</p>
${paras.map((p) => `<p>${esc(p)}</p>`).join('\n')}
<p>Warmly,<br>Akari team</p>`, 'A spot could open up any day now');
  const text = [`Hi ${firstName(e.name)},`, ...paras, 'Warmly,\nAkari team'].join('\n\n');
  return { to: e.email, name: e.name, subject, html, text };
}

// One heads-up email per person, even if they're near the front of several queues. Someone invited
// later in this same run (on another queue) gets only the invite, not a heads-up in the same minute.
for (const [email, list] of primeGroups) {
  if (engaged.has(email)) continue;
  list.forEach((e, i) =>
    actions.push({
      recordId: e.id,
      fields: { Status: 'Primed', 'Primed At': NOW.toISOString() },
      email: i === 0 ? primeEmail(list) : null,
      log: logRow(e, 'Primed', { Source: 'Auto' }),
    }),
  );
}

return actions.map((a) => ({ json: a }));

// ── shared helpers: core ─────────────────────────────
const CFG = $('Config').first().json.cfg;
const NOW = new Date();
const ACTIVE_STATUSES = ['Waiting', 'Primed', 'Invited', 'Tour Requested', 'Warm', 'Not Right Now', 'No Reply'];
const HOLD_STATUSES = ['Invited', 'Tour Requested'];
const HOUR = 3600000;
const DAY = 86400000;

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const toDate = (v) => (v ? new Date(v) : null);
const firstName = (n) => String(n || '').trim().split(/\s+/)[0] || 'there';
const article = (word) => (/^[aeiou]/i.test(String(word || '')) ? 'an' : 'a');
const recordsOf = (nodeName) => $(nodeName).all().flatMap((i) => i.json.records || []);
const fmtTime = (d) =>
  new Date(d).toLocaleString('en-US', {
    timeZone: CFG.timezone, weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short',
  });

// Real tokens come from the "Generate Tokens" (Crypto) node in the executor; Code nodes can't
// reliably reach secure randomness, so they emit this placeholder instead.
const TOKEN = '__TOKEN__';

function normEntry(r) {
  const f = r.fields || {};
  return {
    id: r.id,
    name: f['Name'] || '',
    email: String(f['Email'] || '').trim().toLowerCase(),
    phone: f['Phone'] || '',
    location: f['Location'] || '',
    membership: f['Membership'] || '',
    memberType: f['Member Type'] === 'Existing' ? 'Existing' : 'New',
    joinedAt: toDate(f['Joined At']) || toDate(r.createdTime) || NOW,
    manualRank: typeof f['Manual Rank'] === 'number' ? f['Manual Rank'] : null,
    status: f['Status'] || 'Waiting',
    token: f['Invite Token'] || '',
    invitedAt: toDate(f['Invited At']),
    expiresAt: toDate(f['Invite Expires At']),
    source: f['Invite Source'] || '',
    timeoutCount: Number(f['Timeout Count'] || 0),
    primedAt: toDate(f['Primed At']),
    responseAt: toDate(f['Response At']),
    tourNotes: f['Tour Notes'] || '',
    tourAt: toDate(f['Tour At']),
  };
}

// Cal.com booking page for this person's location (blank if none is set), pre-filled with their name
// and email, and tagged with their row ID so the booking notification can be matched back to them.
function tourBookingUrl(e) {
  const base = String((CFG.tourBookingUrlByLocation || {})[e.location] || '').trim();
  if (!base) return '';
  const params = [['name', e.name], ['email', e.email], ['metadata[entry]', e.id]]
    .filter(([, v]) => v)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join('&');
  return `${base}${base.includes('?') ? '&' : '?'}${params}`;
}

function logRow(e, event, extra = {}) {
  return {
    Summary: `${event} · ${e.email}`,
    Timestamp: NOW.toISOString(),
    Event: event,
    Email: e.email,
    Name: e.name,
    Location: e.location,
    Membership: e.membership,
    'Entry ID': e.id,
    ...extra,
  };
}
// ── end core ─────────────────────────────────────────
// ── shared helpers: pages ─────────────────────────────
function htmlPage(title, bodyHtml, extraHead = '') {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex"><title>${esc(title)} · ${esc(CFG.brandName)}</title>${extraHead}
<style>
body{margin:0;background:#f4f1ec;font-family:Helvetica,Arial,sans-serif;color:#1f1d1a}
main{max-width:520px;margin:0 auto;padding:40px 16px}
.card{background:#fff;border-radius:10px;padding:28px}
.brand{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#8a7f72;margin:0 0 12px}
h1{font-size:22px;margin:0 0 12px}
p{line-height:1.55}
.muted{color:#5b544b;font-size:14px}
.note{background:#fbf3e4;border-radius:6px;padding:10px 12px;font-size:14px}
label{display:block;font-size:14px;margin:16px 0 6px}
textarea{width:100%;box-sizing:border-box;min-height:84px;border:1px solid #c9c1b6;border-radius:6px;padding:10px;font:inherit}
button,.button{display:block;width:100%;box-sizing:border-box;margin-top:18px;padding:13px 16px;border:0;border-radius:6px;background:#1f1d1a;color:#fff;font-size:16px;text-align:center;text-decoration:none;cursor:pointer}
</style></head><body><main><div class="card"><p class="brand">${esc(CFG.brandName)}</p><h1>${esc(title)}</h1>${bodyHtml}</div></main></body></html>`;
}

function redirectPage(url, title, message, label = 'Continue to signup') {
  return htmlPage(
    title,
    `<p>${esc(message)}</p><a class="button" href="${esc(url)}">${esc(label)}</a>`,
    `<meta http-equiv="refresh" content="1;url=${esc(url)}">`,
  );
}
// ── end pages ─────────────────────────────────────────
// GET links from emails only render a confirmation page; the state change happens on POST.
// This stops email link scanners (Outlook Safe Links etc.) from "clicking" a response.
const query = $('Config').first().json.query || {};
const token = String(query.t || '').replace(/[^A-Za-z0-9]/g, '');
const action = String(query.a || '');
const rec = recordsOf('Find Entry by Token (view)')[0];
const reply = (status, title, body) => [{ json: { status, page: htmlPage(title, body), actions: [] } }];

if ($('Find Entry by Token (view)').all().some((i) => i.json.error)) {
  return reply(503, 'Please try again in a minute', '<p>Lots of people are replying right now. Nothing has changed — please refresh this page in a minute.</p>');
}

if (!rec || token.length < 16 || rec.fields['Invite Token'] !== token) {
  return reply(410, 'This link has expired', '<p>This link is no longer active — it may have been replaced by a newer email from us.</p><p class="muted">Please use the most recent email, or reply to it and we\'ll help.</p>');
}

const e = normEntry(rec);
const q = `${e.membership} membership at ${e.location}`;
const calUrl = tourBookingUrl(e);
const COPY = {
  yes: { title: 'Claim your spot', lead: `Confirm you'd like the <strong>${esc(q)}</strong>. We'll take you straight to signup and payment.`, button: 'Yes — continue to signup' },
  tour: calUrl
    ? { title: 'Book a tour first', lead: `We'd love to show you around. Confirm below and we'll hold your <strong>${esc(q)}</strong> spot, then take you to pick a tour time.`, button: 'Choose a tour time' }
    : { title: 'Book a tour first', lead: `We'd love to show you around. Confirm below and we'll hold your <strong>${esc(q)}</strong> spot while we arrange a time.`, button: 'Request a tour', field: ['When suits you? (optional)', 'e.g. weekday evenings, Saturday morning'] },
  notnow: { title: 'Not right now', lead: `No problem — you'll stay on the waitlist for the <strong>${esc(q)}</strong>, and our team will be in touch.`, button: 'Keep me on the list', field: ['Anything we should know? (optional)', ''] },
  no: { title: 'Leave the waitlist', lead: `This removes you from the waitlist for the <strong>${esc(q)}</strong>.`, button: 'Remove me from the waitlist', field: ['Mind telling us why? (optional)', ''] },
  leave: { title: 'Leave your other waitlists', lead: 'This removes you from every other Akari waitlist you are on. Your new membership is not affected.', button: 'Remove me from the other waitlists' },
};
const c = COPY[action];
if (!c) return reply(400, 'Something went wrong', '<p>We couldn\'t read that link. Please use the buttons in your email.</p>');

let note = '';
const lapsed = (e.status === 'Invited' && e.expiresAt && NOW > e.expiresAt) || ['Warm', 'No Reply'].includes(e.status);
if (e.status === 'Signed Up' && action !== 'leave') note = 'You have already claimed this spot.';
else if (e.status === 'Removed') note = 'You are no longer on this waitlist.';
else if (e.status === 'Tour Requested' && action === 'tour') note = 'You\'ve already asked for a tour, and your spot is held.';
else if (['Not Right Now', 'No Longer Interested'].includes(e.status) && (action === 'yes' || action === 'tour')) note = 'You\'ve already told us you weren\'t ready, so this spot was released. If you continue, you\'ll be first in line for the next one.';
else if (lapsed && (action === 'yes' || action === 'tour')) note = `Your ${CFG.holdHours}-hour hold has passed. If you continue, you'll be first in line for the next spot.`;
else if (e.status === 'Invited' && e.expiresAt) note = `Your spot is held until ${esc(fmtTime(e.expiresAt))}.`;

const field = c.field
  ? `<label for="reason">${esc(c.field[0])}</label><textarea id="reason" name="reason" maxlength="1000" placeholder="${esc(c.field[1])}"></textarea>`
  : '';
const body = `<p>${c.lead}</p>${note ? `<p class="note">${note}</p>` : ''}
<form method="POST" action="${esc(CFG.publicWebhookBase)}/respond-confirm" onsubmit="this.querySelector('button').disabled=true">
<input type="hidden" name="t" value="${esc(token)}"><input type="hidden" name="a" value="${esc(action)}">
${field}<button type="submit">${esc(c.button)}</button></form>`;
return reply(200, c.title, body);

